resetState() {
  this.querySelector("#autoConfigEmailForm").reset();
  this.#currentConfig = {};
  this.#touchedInputs = new WeakSet();

  if ("@mozilla.org/userinfo;1" in Cc) {
    const userInfo = Cc["@mozilla.org/userinfo;1"].getService(Ci.nsIUserInfo);
    this.#realName.value = userInfo.fullname;
  }
  this.checkValidEmailForm({ showErrors: false });
}

/**
 * This sets the focus, and the focus needs to be applied to the correct
 * field when this view is either loaded or is revisited by going back.
 */
setState() {
  const focusedInput = this.#realName.value ? this.#email : this.#realName;
  focusedInput.focus();
}

add_task(async function test_setState() {
  subview.setState();
  let userName = "";
  let focusedInput = realName;

  if ("@mozilla.org/userinfo;1" in Cc) {
    userName = Cc["@mozilla.org/userinfo;1"].getService(
      Ci.nsIUserInfo
    ).fullname;
    focusedInput = userName ? email : focusedInput;
  }

  Assert.equal(
    focusedInput,
    subview.ownerDocument.activeElement,
    "Correct input should be focused"
  );

  Assert.equal(realName.value, userName, "Name input value should be correct");
  Assert.equal(email.value, "", "Email input value should be empty");
